import json,numpy as np
from pathlib import Path
P=Path(__file__).resolve().parent;j=json.loads((P/'contact-route-fit.json').read_text());q=np.load(P/'contact-route-pose.npy');v=(q-np.array(j['cupCenter']))@np.array(j['cupRotation']);R=j['parameters']['cupRadius'];H=j['parameters']['cupHeight'];rho=np.linalg.norm(v[:,[0,2]],axis=1);h=v[:,1]
outer=np.interp(h,[0,.025,H-.025,H],[R*.73,R*.8,R,R*.99]);inner=np.interp(h,[.05,H-.025,H],[R*.70,R*.86,R*.88]);inside=(h>0)&(h<H)&(rho<outer)&((h<.05)|(rho>inner));depth=np.minimum.reduce([h,H-h,outer-rho,np.where(h<.05,.05-h,rho-inner)]);ids=np.flatnonzero(inside);sort=ids[np.argsort(-depth[ids])]
result={'scope':'static analytic closed ceramic shell volume classification on body vertices; no face/handle/edge-only intersections or continuous clearance guarantee','insideCeramicVertexCount':len(ids),'maximumVertexPenetrationEstimate':float(depth[ids].max()) if len(ids) else 0,'worst':[{'id':int(i),'depth':float(depth[i]),'position':q[i].tolist(),'cupLocal':v[i].tolist()} for i in sort[:12]],'cupParameters':j['parameters']};(P/'contact-volume-audit.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
